INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Schwachstellen nur in großen Projekten relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte haben Fehler"}, {"text": "Ja", "correct": false, "because": "Überall wichtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit dem Erkennen von Schwachstellen?', 3, '[{"text": "Bugs und Ineffizienzen finden", "correct": true, "because": "Verbessert Qualität"}, {"text": "Code schneller schreiben", "correct": false, "because": "Nicht primär"}, {"text": "Mehr Features", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden helfen, Schwachstellen zu erkennen?', 5, '[{"text": "Code-Reviews", "correct": true, "because": "Findet Fehler früh"}, {"text": "Profiling", "correct": true, "because": "Zeigt Ineffizienzen"}, {"text": "Mehr Entwickler", "correct": false, "because": "Kein direkter Ansatz"}, {"text": "Schnelle Tests", "correct": false, "because": "Tiefe zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Schwachstellen erhöhen Risiken. b) Sie sind immer offensichtlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Oft versteckt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim Erkennen von Schwachstellen?', 4, '[{"text": "Fehlerquellen", "correct": false, "because": "Kern der Analyse"}, {"text": "Performance", "correct": false, "because": "Wichtige Metrik"}, {"text": "Farbschema", "correct": true, "because": "Kein Code-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Schwachstellen ohne Tests erkennbar sind?', 2, '[{"text": "Ja", "correct": true, "because": "Reviews helfen auch"}, {"text": "Nein", "correct": false, "because": "Tests nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool hilft, Schwachstellen zu erkennen?', 3, '[{"text": "Profiler", "correct": true, "because": "Misst Ineffizienzen"}, {"text": "UI-Designer", "correct": false, "because": "Design-Fokus"}, {"text": "Compiler", "correct": false, "because": "Nur Syntax"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Arten von Schwachstellen gibt es?', 5, '[{"text": "Bugs", "correct": true, "because": "Funktionale Fehler"}, {"text": "Ineffizienter Code", "correct": true, "because": "Performance-Probleme"}, {"text": "Zu viele Kommentare", "correct": false, "because": "Kein Schwachpunkt"}, {"text": "Falsche Farben", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Schwachstellen verzögern Projekte. b) Sie sind immer vermeidbar. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht alle vermeidbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um Schwachstellen zu erkennen?', 4, '[{"text": "Tests", "correct": false, "because": "Finden Fehler"}, {"text": "Analyse-Tools", "correct": false, "because": "Unterstützen Erkennung"}, {"text": "UI-Animationen", "correct": true, "because": "Kein Code-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Schwachstellen immer Bugs?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Ineffizienzen"}, {"text": "Ja", "correct": false, "because": "Breiterer Begriff"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren zeigen Schwachstellen?', 4, '[{"text": "Hoher Ressourcenverbrauch", "correct": true, "because": "Ineffizienz"}, {"text": "Fehlerberichte", "correct": true, "because": "Zeigen Bugs"}, {"text": "Schnelle Entwicklung", "correct": false, "because": "Kein Indikator"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Schwachstellen nur in Tests auffallen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Reviews helfen"}, {"text": "Ja", "correct": false, "because": "Mehrere Methoden"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim Erkennen von Schwachstellen?', 3, '[{"text": "Gründliche Analyse", "correct": true, "because": "Findet Ursachen"}, {"text": "Schnelle Fixes", "correct": false, "because": "Erkennung zuerst"}, {"text": "Viele Features", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Schwachstellen beeinträchtigen Qualität. b) Sie sind immer leicht zu finden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Oft versteckt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme verursachen Schwachstellen?', 5, '[{"text": "Abstürze", "correct": true, "because": "Bugs führen dazu"}, {"text": "Langsame Performance", "correct": true, "because": "Ineffizienz"}, {"text": "Zu viele Funktionen", "correct": false, "because": "Kein Schwachpunkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim Erkennen von Schwachstellen unwichtig?', 3, '[{"text": "Fehleranalyse", "correct": false, "because": "Kern der Erkennung"}, {"text": "Metriken", "correct": false, "because": "Zeigen Probleme"}, {"text": "Schriftarten", "correct": true, "because": "Kein Code-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erhöht Schwachstellenerkennung die Kosten?', 3, '[{"text": "Ja", "correct": true, "because": "Aufwand steigt kurzfristig"}, {"text": "Nein", "correct": false, "because": "Langfristig Einsparung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Schwachstellen immer behoben werden müssen?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Impact"}, {"text": "Ja", "correct": false, "because": "Priorisierung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technik hilft, Schwachstellen zu erkennen?', 4, '[{"text": "Statische Analyse", "correct": true, "because": "Findet Fehler vor Laufzeit"}, {"text": "UI-Design", "correct": false, "because": "Design-Fokus"}, {"text": "Schnelltests", "correct": false, "because": "Weniger gründlich"}]');
